#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;
using int64 = long long;

bool isLucky(int64 x) {
    if (x <= 0) return false;
    while (x > 0) {
        int d = x % 10;
        if (d != 4 && d != 7) return false;
        x /= 10;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k;
    cin >> n >> k;

    // We only need to generate the tail of the permutation where the elements are not fixed.
    // The first n - m elements are fixed as 1, 2, ..., n - m.
    // m is chosen such that m! >= k. Since k <= 10^9, m <= 13 (13! > 10^9).
    // We also need m <= n.
    int m = 0;
    int64 fact = 1;
    while (fact < k && m < n) {
        m++;
        fact *= m;
    }

    if (fact < k) {
        cout << -1 << "\n";
        return 0;
    }

    int64 fixed_count = n - m;
    int64 ans = 0;

    // Count lucky numbers among fixed positions (1 to fixed_count).
    // For these positions, a_i = i.
    // We need to count i such that i is lucky.
    // Since fixed_count can be up to 10^9, we generate all lucky numbers up to n.
    vector<int64> lucky_numbers;
    // Generate using BFS/DFS
    vector<int64> q = {4, 7};
    while (!q.empty()) {
        int64 cur = q.back();
        q.pop_back();
        if (cur > n) continue;
        lucky_numbers.push_back(cur);
        q.push_back(cur * 10 + 4);
        q.push_back(cur * 10 + 7);
    }
    sort(lucky_numbers.begin(), lucky_numbers.end());

    // Count lucky numbers in fixed part
    for (int64 ln : lucky_numbers) {
        if (ln <= fixed_count) ans++;
        else break;
    }

    // Process the variable part (positions fixed_count + 1 to n).
    // Elements are fixed_count + 1, ..., n.
    vector<int64> elements;
    for (int64 i = fixed_count + 1; i <= n; ++i) {
        elements.push_back(i);
    }

    // Precompute factorials for the remaining m elements.
    vector<int64> fact_arr(m + 1, 1);
    for (int i = 1; i <= m; ++i) {
        fact_arr[i] = fact_arr[i - 1] * i;
    }

    k--; // 0-indexed
    for (int i = 0; i < m; ++i) {
        int64 f = fact_arr[m - 1 - i];
        int idx = k / f;
        k %= f;

        int64 pos = fixed_count + 1 + i; // 1-based index
        int64 val = elements[idx];
        elements.erase(elements.begin() + idx);

        if (isLucky(pos) && isLucky(val)) {
            ans++;
        }
    }

    cout << ans << "\n";
    return 0;
}
